// The shape of debug@4's src/node.js: supports-color is optional, its absence swallowed.
exports.colors = [6, 2, 3, 4, 5, 1]
try {
  const supportsColor = require('supports-color')
  if (supportsColor && (supportsColor.stderr || supportsColor).level >= 2) exports.colors = [20, 21, 26]
} catch (error) {
  // supports-color doesn't have to be installed
}
